mapper.select:

where ac.emp_id = #{empId}
order by ac.request_date desc, ac.attendance_correction_id desc
limit 100

select count(*)
from attendance_correction
where emp_id = #{empId}
  and work_date = #{workDate}
  and status = 'REQUESTED'

mapper.update:
update attendance_correction
set status = 'CANCELED'
where attendance_correction_id = #{attendanceCorrectionId}
  and emp_id = #{empId}
  and status = 'REQUESTED'

mapper.sql:
where ac.approver_id = #{approverId}

	and ac.status in ('APPROVED', 'REJECTED')
	and ac.status = 'REQUESTED'

mapper.update:
update attendance_correction
set status = 'APPROVED',
    approved_at = #{now}
where attendance_correction_id = #{attendanceCorrectionId}
  and status = 'REQUESTED'

	and approver_id = #{approverId}
	and approver_id is null

update attendance_correction
set status = 'REJECTED',
    approved_at = #{now},
    reject_reason = #{rejectReason}
where attendance_correction_id = #{attendanceCorrectionId}
  and approver_id = #{approverId}
  and status = 'REQUESTED'
